1942	                        if (firstError && firstError.focus) {
1943	                            firstError.focus();
1944	                        }
1945	                        return;
1946	                    }
1947	
1948	                    const submitBtn = document.getElementById('submit-btn');
1949	                    isSubmitting = true;
1950	                    submitBtn.disabled = true;
1951	                    submitBtn.classList.add('loading');
1952	                    const originalHTML = submitBtn.innerHTML;
1953	                    const originalAriaLabel = submitBtn.getAttribute('aria-label');
1954	                    submitBtn.innerHTML = '<span class="spinner" aria-hidden="true" role="presentation"></span>Sending...';
1955	                    submitBtn.setAttribute('aria-label', 'Sending message, please wait');
1956	                    submitBtn.setAttribute('aria-busy', 'true');
1957	
1958	                    const startTime = Date.now();
1959	                    const minLoadingDuration = 500;
1960	
1961	                    const formData = new FormData(contactForm);
1962	                    const endpoint = contactForm.getAttribute('data-endpoint') || '/contact';
1963	                    const controller = new AbortController();
1964	                    const timeoutId = setTimeout(() => controller.abort(), 10000);
1965	
1966	                    fetch(endpoint, {
1967	                        method: 'POST',
1968	                        body: formData,
1969	                        signal: controller.signal
1970	                    })
1971	                    .then(response => {
1972	                        if (!response.ok) {
1973	                            if (response.status === 429) {
1974	                                throw new Error('Too many requests. Please wait a moment and try again.');
1975	                            } else if (response.status >= 500) {
1976	                                throw new Error('Server is temporarily unavailable. Please try again later.');
1977	                            } else if (response.status >= 400) {
1978	                                throw new Error(`Request error (${response.status}). Please check your input and try again.`);
1979	                            }
1980	                            throw new Error(`Server error: ${response.status}`);
1981	                        }
1982	                        return response;
1983	                    })
1984	                    .then(() => {
1985	                        feedback.className = 'form-feedback success';
1986	                        feedback.textContent = '✓ Thank you for your message! We will be in touch soon.';
1987	                        feedback.setAttribute('role', 'status');
1988	                        feedback.setAttribute('aria-live', 'polite');
1989	                        contactForm.reset();
1990	                        try {
1991	                            localStorage.removeItem(FORM_STORAGE_KEY);
1992	                        } catch (e) {
1993	                            console.debug('Could not clear form draft');
1994	                        }
1995	                        inputs.forEach(input => {
1996	                            clearError(input);
1997	                            input.setAttribute('aria-invalid', 'false');
1998	                        });
1999	                        updateMessageCounter();
2000	                        setTimeout(() => feedback.scrollIntoView({ behavior: 'smooth', block: 'center' }), 100);
2001	                    })
2002	                    .catch(error => {
2003	                        feedback.className = 'form-feedback error';
2004	                        feedback.setAttribute('role', 'alert');
2005	                        feedback.setAttribute('aria-live', 'assertive');
2006	                        if (error.name === 'AbortError') {
2007	                            feedback.textContent = 'Request timed out. Please check your connection and try again.';
2008	                        } else if (error instanceof TypeError) {
2009	                            feedback.textContent = 'Connection failed. Please check your internet connection and try again.';
2010	                        } else if (error.message) {
2011	                            feedback.textContent = error.message;
2012	                        } else {
2013	                            feedback.textContent = 'Something went wrong. Please try again in a moment.';
2014	                            console.error('Form submission error:', error);
2015	                        }
2016	                    })
2017	                    .finally(() => {
2018	                        clearTimeout(timeoutId);
2019	                        const elapsedTime = Date.now() - startTime;
2020	                        const remainingDelay = Math.max(0, minLoadingDuration - elapsedTime);
2021	
2022	                        setTimeout(() => {
2023	                            isSubmitting = false;
2024	                            submitBtn.disabled = false;
2025	                            submitBtn.classList.remove('loading');
2026	                            submitBtn.innerHTML = originalHTML;
2027	                            submitBtn.removeAttribute('aria-busy');
2028	                            if (originalAriaLabel) {
2029	                                submitBtn.setAttribute('aria-label', originalAriaLabel);
2030	                            }
2031	                            requestAnimationFrame(() => {
2032	                                try {
2033	                                    feedback.scrollIntoView({ behavior: 'smooth', block: 'center' });
2034	                                    if (feedback.textContent) {
2035	                                        feedback.setAttribute('tabindex', '-1');
2036	                                        feedback.focus({ preventScroll: true });
2037	                                        feedback.removeAttribute('tabindex');
2038	                                    }
2039	                                } catch (e) {
2040	                                    console.error('Error focusing feedback:', e);
2041	                                }
2042	                            });
2043	                        }, remainingDelay);
2044	                    });
2045	                });
2046	            }
2047	        });
2048	    </script>
2049	</body>
